import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mockito;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

@RunWith(MockitoJUnitRunner.class)
public class PropertyListBuilderTest {

    @Test
    public void create_EmptyList_ReturnsEmptyList() {
        // Arrange
        List<Property<?>> properties = new ArrayList<>();

        // Act
        Map<String, Object> map = PropertyListBuilder.builder(properties).create();

        // Assert
        assertEquals(0, ((List<?>) map.get("properties")).size());
    }

    @Test
    public void create_SingleProperty_ReturnsMapWithSingleEntry() {
        // Arrange
        List<Property<?>> properties = new ArrayList<>();
        Property<?> property = mock(Property.class);
        when(property.getName()).thenReturn("test");

        // Act
        Map<String, Object> map = PropertyListBuilder.builder(properties).add(property).create();

        // Assert
        assertEquals(1, ((Map<?, ?>) map.get("properties")).size());
        verify(property).getName();
    }

    @Test
    public void add_NullProperty_ThrowsNullPointerException() {
        // Arrange
        List<Property<?>> properties = new ArrayList<>();

        // Act and Assert
        assertThrows(NullPointerException.class, () -> PropertyListBuilder.builder(properties).add(null));
    }

    @Test
    public void getRootEntries_ReturnsMapWithProperties() {
        // Arrange
        Map<String, Object> map = PropertyListBuilder.builder(new ArrayList<>()).create();

        // Act and Assert
        assertTrue(map.containsKey("properties"));
        verifyNoMoreInteractions();
    }
}
